      exercises: [
        { id: 'd8-7-1', type: 'match', topic: 'S.a.s.', q: 'Accomandatario o accomandante?', pairs: [['Responsabilità illimitata', 'Accomandatario'], ['Può amministrare', 'Accomandatario'], ['Risponde nei limiti della quota', 'Accomandante'], ['Soggetto al divieto di immistione', 'Accomandante']], explain: 'Artt. 2313, 2318, 2320.' },
        { id: 'd8-7-2', type: 'mc', topic: 'Immistione', scenario: 'L’accomandante Elena, senza procura, firma a nome della s.a.s. un contratto con un fornitore e partecipa stabilmente alle scelte di gestione.', q: 'Quali conseguenze?', options: ['Risponde illimitatamente e può essere esclusa', 'Nessuna, se ha agito nell’interesse della società', 'Il contratto è nullo e lei non risponde', 'Diventa accomandataria a tutti gli effetti'], answer: 0, explain: 'Art. 2320 c.c.' },
        { id: 'd8-7-3', type: 'tf', topic: 'Immistione', q: 'L’accomandante può concludere singoli affari per la società se ha una procura speciale.', answer: true, explain: 'Art. 2320 c. 1.' },
        { id: 'd8-7-4', type: 'tf', topic: 'S.a.s.', q: 'L’accomandante che consente che il suo nome compaia nella ragione sociale risponde illimitatamente.', answer: true, explain: 'Art. 2314 c. 2.' },
        { id: 'd8-7-5', type: 'mc', topic: 'S.a.s.', q: 'Come si trasferisce tra vivi la quota dell’accomandante?', options: ['Con il consenso dei soci che rappresentano la maggioranza del capitale', 'Liberamente, senza bisogno di alcun consenso', 'Con il consenso unanime di tutti i soci, accomandanti compresi', 'Con la girata di un titolo azionario'], answer: 0, explain: 'Art. 2322 c.c.' },
        { id: 'd8-7-6', type: 'mc', topic: 'S.a.s.', scenario: 'L’unico accomandatario di una s.a.s. muore e gli eredi non entrano.', q: 'Cosa succede?', options: ['Se entro sei mesi non si ricostituisce la categoria, la società si scioglie', 'La società si trasforma in s.r.l.', 'Gli accomandanti diventano accomandatari automaticamente', 'La società continua senza amministratori'], answer: 0, explain: 'Art. 2323 c.c.' },
        { id: 'd8-7-7', type: 'tf', topic: 'S.a.s.', q: 'Nella s.a.s. irregolare gli accomandanti perdono sempre la responsabilità limitata.', answer: false, explain: 'La conservano, salvo che abbiano partecipato alle operazioni sociali (art. 2317).' },
        { id: 'd8-7-8', type: 'mc', topic: 'Società semplice', q: 'Quale attività può svolgere la società semplice?', options: ['Agricola o professionale, non commerciale', 'Qualunque attività, anche commerciale', 'Solo attività finanziaria', 'Solo attività consortile'], answer: 0, explain: 'Art. 2249 c. 2.' },
        { id: 'd8-7-9', type: 'tf', topic: 'Società semplice', q: 'Nella società semplice il patto che limita la responsabilità di un socio senza poteri di rappresentanza è opponibile ai terzi se portato a loro conoscenza.', answer: true, explain: 'Art. 2267 c. 2.' },
        { id: 'd8-7-10', type: 'tf', topic: 'Società semplice', q: 'La disciplina della società semplice si applica alla s.n.c. per quanto non diversamente previsto.', answer: true, explain: 'È il prototipo delle società di persone (art. 2293).' },
        { id: 'd8-7-11', type: 'tf', topic: 'S.a.s.', q: 'Le quote della s.a.s. possono essere rappresentate da azioni.', answer: false, explain: 'Art. 2313 c. 2.' },
      ],
